package com.mycompany.greenbasket;
import java.io.*;import java.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;
@WebServlet("/CheckoutServlet") public class CheckoutServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{UserReg u=(UserReg)r.getSession().getAttribute("loggedUser");if(u==null){s.sendRedirect("UserLogin.jsp?checkout=1");return;}Map<Integer,Integer> cart=(Map<Integer,Integer>)r.getSession().getAttribute("cart");if(cart==null||cart.isEmpty()){s.sendRedirect("products.jsp");return;}int id=new OrderDAO().createOrder(u,cart,r.getParameter("address"));if(id>0){cart.clear();s.sendRedirect(r.getContextPath()+"/orders.jsp?placed="+id);}else{r.setAttribute("errorMessage","Order could not be placed. Please check product stock.");r.getRequestDispatcher("/checkout.jsp").forward(r,s);}}}
